UPDATE ivs_part_catalog
SET data = jsonb_set(
  data,
  '{spec,shapes}',
  (data->'spec'->'shapes') || '[{"x": 0, "y": -0.05, "z": 0, "op": "add", "rx": 0, "ry": 0, "rz": 0, "type": "import", "color": "#cccccc", "fileName": "작은바퀴_바깥면.stl", "brightness": 100, "fileDataUrl": "data:application/octet-stream;base64,", "paint": true}]'::jsonb
)
WHERE id = '1bfa609d-b5b7-459a-8598-8fc07feafc3a'
  AND jsonb_array_length(data->'spec'->'shapes') = 1
RETURNING jsonb_array_length(data->'spec'->'shapes') AS n;
